// Models operating Connect: REST API lifecycle, error-tolerance + DLQ, JMX metrics.
package com.bank.connectops.demo;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ConnectOpsDemo {

    private static final Logger log = Logger.getLogger("ConnectOps");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JmxMetrics metrics = new JmxMetrics();
        DeadLetterQueue dlq = new DeadLetterQueue();
        SinkTask task = new SinkTask(/*errorsToleranceAll*/ true, dlq, metrics);
        ConnectRestApi rest = new ConnectRestApi(task);

        log.info("=== REST: create connector ===");
        rest.createConnector("txn-s3-sink");

        log.info("=== process a batch with one poison record (DLQ, task survives) ===");
        task.put(List.of(
            new Record("TXN-1", "SAV2001", new BigDecimal("20000"), true),
            new Record("TXN-BAD", "???", null, false),   // unparseable → DLQ
            new Record("TXN-2", "CUR3001", new BigDecimal("50000"), true)
        ));

        log.info("=== JMX: read metrics ===");
        metrics.report();

        log.info("=== REST: pause for storage maintenance, then resume ===");
        rest.pause("txn-s3-sink");
        rest.resume("txn-s3-sink");

        log.info("=== task fails on infra error → status FAILED → restart ===");
        task.failInfrastructure();
        log.info(() -> "status = " + rest.status("txn-s3-sink"));
        rest.restartTask("txn-s3-sink");
        log.info(() -> "status = " + rest.status("txn-s3-sink"));
    }
}

