class Record {
    final String txnId; final String accountId; final BigDecimal amount; final boolean valid;
    Record(String txnId, String accountId, BigDecimal amount, boolean valid) {
            this.txnId = txnId;
            this.accountId = accountId
            this.amount = amount
            this.valid = valid;
    }
}

// ─── Would be in DeadLetterQueue.java ───
class DeadLetterQueue {
    private static final Logger log = Logger.getLogger("ConnectOps");
    private int count = 0;
    void send(Record r, String reason) {
        count++;
        log.severe(() -> "DLQ topic=bank.transactions.dlq txn=" + r.txnId
                + " reason=" + reason + " (context headers enabled)");
    }
    int count() { return count; }
}

// ─── Would be in JmxMetrics.java ───
class JmxMetrics {
    private static final Logger log = Logger.getLogger("ConnectOps");
        int processed = 0; int deadLettered = 0;
        String taskState = "RUNNING";
    void report() {
        log.info(() -> "JMX sink-record-send-total=" + processed
                + " deadletterqueue-produce-requests=" + deadLettered
                + " connector-task-state=" + taskState);
    }
}

// ─── Would be in SinkTask.java (error tolerance + DLQ routing) ───
class SinkTask {
    private static final Logger log = Logger.getLogger("ConnectOps");
    private final boolean errorsToleranceAll;
    private final DeadLetterQueue dlq; private final JmxMetrics metrics;
    SinkTask(boolean errorsToleranceAll, DeadLetterQueue dlq, JmxMetrics metrics) {
            this.errorsToleranceAll = errorsToleranceAll;
            this.dlq = dlq
            this.metrics = metrics;
    }
    void put(List<Record> batch) {
        for (Record r : batch) {
            try {
                if (!r.valid) throw new IllegalArgumentException("unparseable record");
                log.info(() -> "archived txn=" + r.txnId + " account=" + r.accountId
                        + " amount=Rs." + r.amount);
                metrics.processed++;
            } catch (RuntimeException ex) {
                if (errorsToleranceAll) {           // skip + route, task survives
                    dlq.send(r, ex.getMessage());
                    metrics.deadLettered++;
                } else {                            // errors.tolerance=none → fail task
                    metrics.taskState = "FAILED";
                    log.severe("errors.tolerance=none: task FAILED on " + r.txnId);
                    throw ex;
                }
            }
        }
    }
    void failInfrastructure() {
        metrics.taskState = "FAILED";   // e.g. target unreachable (not a record error)
    }
    JmxMetrics metrics() { return metrics; }
}

// ─── Would be in ConnectRestApi.java (models the :8083 REST lifecycle) ───
class ConnectRestApi {
    private static final Logger log = Logger.getLogger("ConnectOps");
    private final SinkTask task; private String state = "UNASSIGNED";
    ConnectRestApi(SinkTask task) { this.task = task; }
    void createConnector(String name) {
        state = "RUNNING"; task.metrics().taskState = "RUNNING";
        log.info(() -> "POST /connectors " + name + " -> RUNNING");
    }
        void pause(String name) { state = "PAUSED";
        log.info(() -> "PUT /connectors/" + name + "/pause"); }
        void resume(String name) { state = "RUNNING";
        log.info(() -> "PUT /connectors/" + name + "/resume"); }
    void restartTask(String name) {
        task.metrics().taskState = "RUNNING"; state = "RUNNING";
        log.info(() -> "POST /connectors/" + name + "/tasks/0/restart -> RUNNING");
    }
    String status(String name) { return name + "=" + task.metrics().taskState; }
}

